static void* rd_mono_icall_bind(const char* name, uintptr_t guest)
{
    int low = 0;
    int high = (int)(sizeof(rd_mono_icalls) / sizeof(rd_mono_icalls[0])) - 1;
    while (low <= high) {
        int middle = low + (high - low) / 2;
        int order = strcmp(name, rd_mono_icalls[middle].name);
        if (order < 0) high = middle - 1;
        else if (order > 0) low = middle + 1;
        else {
            *rd_mono_icalls[middle].guest = guest;
            return rd_mono_icalls[middle].host;
        }
    }
    return NULL;
}
